"""Intermediate representation: three-address code generated by a syntax-directed
(post-order) traversal of the annotated AST."""
from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Optional

from . import ast as A
from .ops import is_literal

BINOPS = {"+", "-", "*", "/", "%", "<", ">", "<=", ">=", "==", "!="}
UNOPS = {"neg", "not", "itof"}
DEFINES = BINOPS | UNOPS | {"="}
BRANCHES = {"goto", "iffalse", "iftrue"}
DEFAULTS = {"int": "0", "float": "0.0", "bool": "false", "string": '""'}


@dataclass
class Instr:
    op: str
    arg1: Optional[str] = None
    arg2: Optional[str] = None
    result: Optional[str] = None
    line: int = 0

    def text(self) -> str:
        o = self.op
        if o == "label":
            return f"{self.result}:"
        if o == "goto":
            return f"goto {self.result}"
        if o in ("iffalse", "iftrue"):
            return f"{o} {self.arg1} goto {self.result}"
        if o == "print":
            return f"print {self.arg1}"
        if o == "=":
            return f"{self.result} = {self.arg1}"
        if o == "neg":
            return f"{self.result} = -{self.arg1}"
        if o == "not":
            return f"{self.result} = !{self.arg1}"
        if o == "itof":
            return f"{self.result} = (float) {self.arg1}"
        return f"{self.result} = {self.arg1} {o} {self.arg2}"

    def to_dict(self) -> dict:
        return {"op": self.op, "arg1": self.arg1, "arg2": self.arg2, "result": self.result, "line": self.line, "text": self.text()}

    def copy(self, **kw) -> "Instr":
        return replace(self, **kw)


def is_temp(x) -> bool:
    return isinstance(x, str) and len(x) > 1 and x[0] == "t" and x[1:].isdigit()


def defs(ins: Instr) -> Optional[str]:
    return ins.result if ins.op in DEFINES else None


def uses(ins: Instr) -> list[str]:
    if ins.op in DEFINES or ins.op in ("iffalse", "iftrue", "print"):
        return [a for a in (ins.arg1, ins.arg2) if a is not None and not is_literal(a)]
    return []


class IRGen:
    def __init__(self, var_types: dict[str, str]):
        self.var_types = var_types
        self.code: list[Instr] = []
        self.nt = 0
        self.nl = 0
        self.line = 0

    def temp(self) -> str:
        self.nt += 1
        return f"t{self.nt}"

    def label(self) -> str:
        self.nl += 1
        return f"L{self.nl}"

    def emit(self, op, a1=None, a2=None, res=None) -> None:
        self.code.append(Instr(op, a1, a2, res, self.line))

    # ------------------------------------------------------------- exprs
    def expr(self, e: A.Expr) -> str:
        if isinstance(e, A.Literal):
            return e.value
        if isinstance(e, A.Ident):
            return e.uid
        if isinstance(e, A.Unary):
            v = self.expr(e.operand)
            t = self.temp()
            self.emit("neg" if e.op == "-" else "not", v, None, t)
            return t
        if isinstance(e, A.Binary):
            if e.op in ("&&", "||"):
                t, end = self.temp(), self.label()
                self.emit("=", self.expr(e.left), None, t)
                self.emit("iffalse" if e.op == "&&" else "iftrue", t, None, end)
                self.emit("=", self.expr(e.right), None, t)
                self.emit("label", None, None, end)
                return t
            l = self.expr(e.left)
            r = self.expr(e.right)
            t = self.temp()
            self.emit(e.op, l, r, t)
            return t
        raise TypeError(e)

    def store(self, uid: str, value: A.Expr) -> None:
        v = self.expr(value)
        if self.var_types.get(uid) == "float" and value.ty == "int":
            self.emit("itof", v, None, uid)
        else:
            self.emit("=", v, None, uid)

    # -------------------------------------------------------- statements
    def stmt(self, s: A.Node) -> None:
        self.line = s.line
        if isinstance(s, A.VarDecl):
            if s.init is not None:
                self.store(s.uid, s.init)
            else:
                self.emit("=", DEFAULTS[s.vtype], None, s.uid)
        elif isinstance(s, A.Assign):
            self.store(s.uid, s.value)
        elif isinstance(s, A.Print):
            self.emit("print", self.expr(s.value))
        elif isinstance(s, A.Block):
            for x in s.body:
                self.stmt(x)
        elif isinstance(s, A.If):
            c = self.expr(s.cond)
            lend = self.label()
            lelse = self.label() if s.alt is not None else lend
            self.emit("iffalse", c, None, lelse)
            self.stmt(s.then)
            if s.alt is not None:
                self.emit("goto", None, None, lend)
                self.emit("label", None, None, lelse)
                self.stmt(s.alt)
            self.emit("label", None, None, lend)
        elif isinstance(s, A.While):
            top, end = self.label(), self.label()
            self.emit("label", None, None, top)
            c = self.expr(s.cond)
            self.emit("iffalse", c, None, end)
            self.stmt(s.body)
            self.line = s.line
            self.emit("goto", None, None, top)
            self.emit("label", None, None, end)


def generate(program: A.Program, var_types: dict[str, str]) -> list[Instr]:
    g = IRGen(var_types)
    for s in program.body:
        g.stmt(s)
    return g.code
